        }
        body {
            font-family: 'Yu Mincho', '游明朝体', 'Noto Serif SC', serif;
            color: var(--text-color); margin: 0; padding: 0; background-color: transparent;
        }
        #status-card-container-final {
            background-color: var(--bg-color); border: 1px solid var(--border-color);
