        .collapse-btn { font-size: 0.9em; color: var(--accent-color); }
        .status-content { transition: all 0.4s ease-in-out; overflow: hidden; max-height: 5000px; }
        .status-content.collapsed { max-height: 0; padding-top: 0; padding-bottom: 0; margin-top: 0; }
        .tab-buttons { display: flex; border-bottom: 1px solid var(--border-color); margin: 15px 0; }
        .tab-button { flex: 1; padding: 10px 15px; cursor: pointer; background: none; border: none; color: var(--text-color); font-family: inherit; font-size: 1em; border-bottom: 3px solid transparent; transition: all 0.3s; text-align: center; }
        .tab-button:hover { background-color: var(--accent-color-light); }
        .tab-button.active { color: var(--accent-color); border-bottom: 3px solid var(--accent-color); }
        .tab-content { display: none; animation: fadeIn 0.5s; }
        .tab-content.active { display: block; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .card { background-color: var(--panel-bg); border-radius: 8px; padding: 15px; margin-bottom: 15px; border: 1px solid var(--border-color); }
        .card-header { font-size: 1.1em; font-weight: bold; color: var(--header-text); margin-bottom: 10px; padding-bottom: 5px; border-bottom: 1px solid var(--border-color); }
        .info-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 10px; }
        .info-item { line-height: 1.7; white-space: pre-wrap; }
        .info-item b { color: var(--accent-color); }
        .simple-list { list-style: none; padding: 0; margin: 0; }
        .simple-list li { padding: 8px 0; border-bottom: 1px dashed var(--border-color); line-height: 1.6; }
        .simple-list li:last-child { border-bottom: none; }
        .simple-list b { color: var(--header-text); }
        .character-card { margin-top: 15px; }
        .radar-chart-container { position: relative; margin: auto; height: 300px; width: 100%; max-width: 300px; }
    </style>
</head>
<body>
    <div id="status-card-container-final">
        <div class="status-header">
            <span class="header-title">角色状态</span>
            <span class="collapse-btn">[ 收起 ]</span>
        </div>
        <div class="status-content">
            <div class="tab-buttons">
                <button class="tab-button active" data-tab="core-panel">核心面板</button>
                <button class="tab-button" data-tab="attributes-panel">属性</button>
                <button class="tab-button" data-tab="skills-panel">功法装备</button>
                <button class="tab-button" data-tab="relations-panel">人物关系</button>
                <!-- 系统标签页按钮 -->
                <button class="tab-button" data-tab="system-panel">系统</button>
            </div>
            <div class="tab-content-wrapper">
                <div id="core-panel" class="tab-content active"></div>
                <div id="attributes-panel" class="tab-content">
                    <div class="card">
                        <div class="card-header">基础属性</div>
                        <div class="radar-chart-container"><canvas id="radar-chart"></canvas></div>
                    </div>
                    <div id="special-attributes-section"></div>
                </div>
                <div id="skills-panel" class="tab-content"></div>
                <div id="relations-panel" class="tab-content"></div>
                <!-- 系统标签页内容容器 -->
                <div id="system-panel" class="tab-content"></div>
            </div>
        </div>
    </div>

    <script>
        (function() {
            const container = document.getElementById('status-card-container-final');
            if (container.dataset.rendered) return;
            container.dataset.rendered = 'true';

            const rawText = `$1`;

            function parseRawText(text) {
                const data = {
                    core: { kvs: {}, 声望: [], 持有物品: [] },
                    attributes: { 基础属性: {}, 特殊体质: [], 特殊血脉: [], 特殊气运: [] },
                    skills: { 功法: [], 神通: [], 法宝: [] },
                    relations: { 道侣: [], 当前互动: [] },
                    system: { kvs: {}, 主线任务: [], 支线任务: [] }
                };
                let currentSection = null, currentBlock = null, currentCharacter = null;
                const lines = text.split('\n');
                for (const line of lines) {
                    const trimmedLine = line.trim();
                    if (!trimmedLine) continue;
                    let match;
                    if (match = trimmedLine.match(/^\[(.*?)\]$/)) {
                        const sectionName = match[1];
                        if (sectionName === '核心面板') currentSection = data.core;
                        else if (sectionName.includes('属性')) currentSection = data.attributes;
                        else if (sectionName === '功法装备') currentSection = data.skills;
                        else if (sectionName === '人物关系') currentSection = data.relations;
                        else if (sectionName === 'MudShooter的小卖部') currentSection = data.system;
                        else currentSection = null;
                        currentBlock = null; currentCharacter = null;
                    } else if (match = trimmedLine.match(/^【(.*?)】$/)) {
                        currentBlock = match[1]; currentCharacter = null;
                    } else if (currentSection === data.relations && currentBlock && !trimmedLine.includes(':')) {
                        currentCharacter = { name: trimmedLine, details: [] };
                        currentSection[currentBlock].push(currentCharacter);
                    } else {
                        const parts = trimmedLine.split(/:(.*)/s);
                        if (parts.length < 2 || !currentSection) continue;
                        const key = parts[0].trim(); const value = parts[1].trim();
                        if (currentCharacter && currentSection === data.relations) {
                            currentCharacter.details.push({ key, value });
                        } else if (currentBlock) {
                            if (currentSection[currentBlock]) {
                                if (Array.isArray(currentSection[currentBlock])) currentSection[currentBlock].push({ key, value });
                                else currentSection[currentBlock][key] = value;
                            }
                        } else if (currentSection.kvs) {
                            currentSection.kvs[key] = value;
                        }
                    }
                }
                return data;
            }

            const data = parseRawText(rawText);

            function renderListBlock(title, items) {
                if (!items || items.length === 0) return `<div class="card"><div class="card-header">${title}</div><div class="info-item">暂无</div></div>`;
                const listHtml = items.map(item => `<li><b>${item.key}:</b> ${item.value}</li>`).join('');
                return `<div class="card"><div class="card-header">${title}</div><ul class="simple-list">${listHtml}</ul></div>`;
            }

            // --- 渲染 ---
            let coreHtml = `<div class="card"><div class="info-grid">${Object.entries(data.core.kvs).map(([k,v])=>`<div class="info-item"><b>${k}:</b> ${v}</div>`).join('')}</div></div>`;
            coreHtml += renderListBlock('声望', data.core.声望);
            coreHtml += renderListBlock('持有物品', data.core.持有物品);
            container.querySelector('#core-panel').innerHTML = coreHtml;

            const basicAttrValues = {'根骨':0,'悟性':0,'智商':0,'情商':0,'魅力':0};
            Object.keys(basicAttrValues).forEach(k => {if(data.attributes.基础属性[k]) basicAttrValues[k] = parseInt(data.attributes.基础属性[k])||0;});
            let specialAttrHtml = renderListBlock('特殊体质', data.attributes.特殊体质);
            specialAttrHtml += renderListBlock('特殊血脉', data.attributes.特殊血脉);
            specialAttrHtml += renderListBlock('特殊气运', data.attributes.特殊气运);
            container.querySelector('#special-attributes-section').innerHTML = specialAttrHtml;

            let skillsHtml = renderListBlock('功法', data.skills.功法);
            skillsHtml += renderListBlock('神通', data.skills.神通);
            skillsHtml += renderListBlock('法宝', data.skills.法宝);
            container.querySelector('#skills-panel').innerHTML = skillsHtml;

            let relationsHtml = '';
            for(const blockTitle of ['道侣', '当前互动']){
                const characters = data.relations[blockTitle];
                if (!characters || characters.length === 0) continue;
                relationsHtml += `<div class="card"><div class="card-header">${blockTitle}</div>`;
                characters.forEach(char => {
                    const detailsHtml = char.details.map(d => `<b>${d.key}:</b> ${d.value}`).join('<br>');
                    relationsHtml += `<div class="character-card card"><div class="card-header">${char.name}</div><div class="info-item">${detailsHtml}</div></div>`;
                });
                relationsHtml += `</div>`;
            }
            container.querySelector('#relations-panel').innerHTML = relationsHtml || '<div class="card"><div class="info-item">暂无</div></div>';

            // 【修改】小卖部渲染逻辑
            let systemHtml = `<div class="card"><div class="card-header">MudShooter的小卖部</div><div class="info-item">${Object.entries(data.system.kvs).map(([k,v])=>`<b>${k}:</b> ${v}`).join('<br>')}</div></div>`;
            systemHtml += renderListBlock('主线任务', data.system.主线任务);
            systemHtml += renderListBlock('支线任务', data.system.支线任务);
            container.querySelector('#system-panel').innerHTML = systemHtml;

            // 雷达图
            new Chart(container.querySelector('#radar-chart').getContext('2d'), {
                type: 'radar', data: { labels: Object.keys(basicAttrValues), datasets: [{ label: '基础属性', data: Object.values(basicAttrValues), backgroundColor: 'rgba(97, 175, 239, 0.2)', borderColor: 'rgba(97, 175, 239, 1)' }] },
                options: { responsive: true, maintainAspectRatio: false, scales: { r: { angleLines: { color: 'rgba(255, 255, 255, 0.2)' }, grid: { color: 'rgba(255, 255, 255, 0.2)' }, pointLabels: { color: '#e0e1e6', font: { family: "'Yu Mincho', '游明朝体', 'Noto Serif SC', serif", size: 12 } }, suggestedMin: 0 } }, plugins: { legend: { display: false } } }
            });

            // --- 交互事件 ---
            container.querySelector('.status-header').addEventListener('click', (e) => {
                const content = container.querySelector('.status-content');
                content.classList.toggle('collapsed');
                e.currentTarget.querySelector('.collapse-btn').textContent = content.classList.contains('collapsed') ? '[ 展开 ]' : '[ 收起 ]';
            });
            // 标签页切换逻辑
            container.querySelectorAll('.tab-button').forEach(button => {
                button.addEventListener('click', () => {
                    container.querySelectorAll('.tab-button').forEach(btn => btn.classList.remove('active'));
                    button.classList.add('active');
                    container.querySelectorAll('.tab-content').forEach(content => {
                        content.id === button.dataset.tab ? content.classList.add('active') : content.classList.remove('active');
                    });
                });
            });
        })();
    </script>
</body>
</html>
