    <title>角色状态</title>
    <style>
        /*
         *  这是一个纯CSS的简约折叠状态栏。
         *  它不包含任何JavaScript，利用隐藏的复选框技巧实现折叠。
         *  默认状态为展开。
        */

        #css-collapsible-panel {
            /* 1. 设置底色和字体 */
            background-color: #f8f4e6;
            font-family: 'Yu Mincho', '游明朝体', 'Noto Serif SC', serif;

            /* 2. 基础样式 */
            color: #2b2b2b;
            padding: 10px;
            border-radius: 8px;
            border: 1px solid rgba(0, 0, 0, 0.1);
            max-width: 100%;
            box-sizing: border-box;
            font-size: 13px; /* 您可以修改 13px 为任何您需要的大小, 默认13像素 */
            overflow: hidden; /* 防止动画溢出 */
        }

        /* 3. 隐藏真正的复选框，它是幕后的功能核心 */
        .hidden-checkbox {
            display: none;
        }

        .panel-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            cursor: pointer; /* 提示用户这里可以点击 */
            padding-bottom: 10px;
            margin-bottom: 10px;
            border-bottom: 1px solid rgba(0, 0, 0, 0.1);
        }

        .panel-title {
            font-size: 1.3em;
            font-weight: bold;
            color: #16160e;
        }

        .toggle-text {
            font-size: 0.8em;
            font-weight: normal;
            color: #555;
        }

        .panel-content {
            margin: 0;
            padding: 0;
            max-height: 5000px; /* 设置一个足够大的高度，确保内容完全显示 */
            overflow: hidden;
            transition: max-height 0.4s ease-in-out, margin 0.4s ease-in-out; /* 平滑的折叠动画 */
        }

        /* 4. 关键：当复选框被选中时，折叠内容区域 */
        .hidden-checkbox:checked + .panel-header + .panel-content {
            max-height: 0;
            margin-bottom: -10px; /* 抵消header的margin-bottom，使边框贴合 */
        }

        .hidden-checkbox:checked + .panel-header {
             border-bottom-color: transparent; /* 折叠时隐藏底部分割线 */
        }

        /* 5. 切换 [展开] / [收起] 文字 */
        .toggle-expand { display: none; }
        .hidden-checkbox:checked + .panel-header .toggle-collapse { display: none; }
        .hidden-checkbox:checked + .panel-header .toggle-expand { display: block; }

        .status-content-pre {
            margin: 0;
            padding: 0;
            font-family: inherit;
            font-size: 1em;
            line-height: 1.6;
            white-space: pre-wrap;
            word-wrap: break-word;
        }
    </style>
</head>
<body>

    <div id="css-collapsible-panel">

        <!-- 这个隐藏的复选框是实现功能的“开关” -->
        <input type="checkbox" id="collapse-toggle" class="hidden-checkbox">

        <!-- <label>标签让我们可以通过点击文字来控制复选框的状态 -->
        <label for="collapse-toggle" class="panel-header">
            <span class="panel-title">状态栏</span>
            <span class="toggle-text">
                <span class="toggle-collapse">[ 收起 ]</span>
                <span class="toggle-expand">[ 展开 ]</span>
            </span>
        </label>

        <!-- 要被折叠的内容 -->
        <div class="panel-content">
            <pre class="status-content-pre">$1</pre>
        </div>

    </div>

</body>
</html>
