<body class="bg-gray-900 text-gray-200 p-2 md:p-4">

    <div id="StatusBlockContainer" class="status-panel-cyber max-w-7xl mx-auto rounded-2xl p-4 md:p-6 space-y-6">

        <section id="core-panel-target"></section>
        <div class="section-divider"></div>

        <div class="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <section id="core-subpanel-target" class="lg:order-3 lg:col-span-2"></section>
            <section id="attributes-panel-target" class="lg:order-2 lg:col-span-1"></section>
            <section id="skills-panel-target" class="lg:order-1 lg:col-span-2"></section>
            <section id="relations-panel-target" class="lg:order-4 lg:col-span-1"></section>
        </div>

        <div id="system-panel-wrapper"></div>

    </div>

    <script>
    (function() {
        const container = document.getElementById('StatusBlockContainer');
        if (container.dataset.rendered) return;
        container.dataset.rendered = 'true';

        const rawText = `$1`;

        function parseRawText(text) {
            const data = {
                core: { kvs: {}, 声望: [], 持有物品: [] },
                attributes: { 基础属性: [], 特殊体质: [], 特殊血脉: [], 特殊气运: [] },
                skills: { 功法: [], 神通: [], 法宝: [] },
                relations: { 道侣: [], 当前互动: [] },
                // 【修改】初始化新增的任务数组
                system: { kvs: {}, 主线任务: [], 支线任务: [], 紧急任务: [], 专属任务: [], 天谴任务: [] }
            };
            let currentSection = null, currentBlock = null, currentCharacter = null;
            const lines = text.split('\n').filter(l => l.trim() !== '');

            for (const line of lines) {
                const trimmedLine = line.trim();
                let match;
                if (match = trimmedLine.match(/^\[(.*?)\]$/)) {
                    const sectionName = match[1];
                    if (sectionName === '核心面板') currentSection = data.core;
                    else if (sectionName.includes('属性')) currentSection = data.attributes;
                    else if (sectionName === '功法装备') currentSection = data.skills;
                    else if (sectionName === '人物关系') currentSection = data.relations;
                    else if (sectionName === 'MudShooter的小卖部') currentSection = data.system;
                    else currentSection = null;
                    currentBlock = null; currentCharacter = null;
                } else if (match = trimmedLine.match(/^【(.*?)】$/)) {
                    currentBlock = match[1]; currentCharacter = null;
                } else if (currentSection === data.relations && currentBlock && !trimmedLine.includes(':') && trimmedLine !== '暂无' && trimmedLine !== '无') {
                    currentCharacter = { name: trimmedLine, details: [] };
                    currentSection[currentBlock].push(currentCharacter);
                } else {
                    const parts = trimmedLine.split(/:(.*)/s);
                    if (parts.length < 2 || !currentSection) continue;
                    const key = parts[0].trim(); const value = parts[1].trim();
                    if (currentCharacter && currentSection === data.relations) {
                        currentCharacter.details.push({ key, value });
                    } else if (currentBlock && currentSection[currentBlock]) {
                        // 解析器是动态的，无需修改即可支持新任务类型
                        currentSection[currentBlock].push({ key, value });
                    } else if (currentSection.kvs) {
                        currentSection.kvs[key] = value;
                    }
                }
            }
            return data;
        }

        const data = parseRawText(rawText);

        function createNestedTabs(tabData, containerId) {
            const hasContent = tabData.some(tab => tab.content.trim() !== '' && !tab.content.includes('italic'));
            if (!hasContent) return `<div class="p-4 bg-black/20 rounded-lg border border-gray-700/50 text-center text-gray-400 italic">暂无信息</div>`;
            const buttons = tabData.map((tab, index) => `<button class="tab-button ${index === 0 ? 'active' : ''}" data-tab="${containerId}-${index}">${tab.title}</button>`).join('');
            const contents = tabData.map((tab, index) => `<div class="tab-content ${index === 0 ? 'active' : ''}" id="${containerId}-${index}">${tab.content}</div>`).join('');
            return `<div class="nested-tabs-container" id="${containerId}">
                        <div class="tab-buttons">${buttons}</div>
                        <div class="tab-content-wrapper">${contents}</div>
                    </div>`;
        }

        function renderCorePanel() {
            const kvs = data.core.kvs;
            const lifeMatch = (kvs['生命'] || '').match(/\[(\d+)\/(\d+)\]/) || [0,0,1];
            const manaMatch = (kvs['灵力'] || '').match(/\[(\d+)\/(\d+)\]/) || [0,0,1];
            const realmMatch = (kvs['境界'] || '').match(/(.*?)\[(\d+)\/(\d+)\]/) || [0,"",0,1];
            const realmParts = (realmMatch[1] || '无境界').split(/(\S+境)(\S+)/);
            const lifePercent = lifeMatch[2] > 0 ? (lifeMatch[1]/lifeMatch[2]) * 100 : 0;
            const manaPercent = manaMatch[2] > 0 ? (manaMatch[1]/manaMatch[2]) * 100 : 0;
            const cultivationBarStyle = `background-image: linear-gradient(to right, #8b5cf6, #ec4899, #f59e0b); width: ${realmMatch[3] > 0 ? (realmMatch[2] / realmMatch[3]) * 100 : 0}%;`;

            return `
                <div class="grid grid-cols-1 md:grid-cols-3 gap-6 items-center border-b border-yellow-700/20 pb-6">
                    <div class="md:col-span-2 space-y-4">
                        <div class="flex items-center space-x-4">
                            <h1 class="text-4xl font-bold text-yellow-300 panel-title">${kvs['姓名'] || '未知'}</h1>
                            <span class="inline-block px-3 py-1 text-sm bg-yellow-900/50 text-yellow-200 border border-yellow-700/50 rounded-full">${kvs['所属势力'] || '无'}</span>
                        </div>
                        <div class="text-gray-400 text-sm">
                            <p><span class="font-semibold">位置:</span> ${kvs['位置'] || '未知'}</p>
                            <p><span class="font-semibold">时间:</span> ${kvs['时间'] || '未知'}</p>
                        </div>
                    </div>
                    <div class="space-y-3 text-sm">
                        <div>
                            <div class="flex justify-between mb-1"><span>生命:</span><span class="font-mono highlight-value">${lifeMatch[1]} / ${lifeMatch[2]}</span></div>
                            <div class="w-full progress-bar-bg rounded-full h-2.5"><div class="bg-green-500 h-2.5 rounded-full" style="width: ${lifePercent}%"></div></div>
                        </div>
                        <div>
                            <div class="flex justify-between mb-1"><span>灵力:</span><span class="font-mono highlight-value">${manaMatch[1]} / ${manaMatch[2]}</span></div>
                            <div class="w-full progress-bar-bg rounded-full h-2.5"><div class="bg-blue-500 h-2.5 rounded-full" style="width: ${manaPercent}%"></div></div>
                        </div>
                        <p><span class="font-semibold text-gray-400">状态: </span><span class="text-green-400">${kvs['状态'] || '正常'}</span></p>
                    </div>
                </div>
                <div class="mt-4 flex items-center justify-between flex-wrap gap-2">
                    <div>
                        <span class="text-lg text-yellow-400">境界: </span>
                        <span class="text-2xl font-semibold text-white">${realmParts[1] || ''}</span>
                        <span class="text-xl text-yellow-300">${realmParts[2] || ''}</span>
                    </div>
                    <div class="text-right">
                        <div class="text-sm text-gray-400">修为进度</div>
                        <div class="font-mono text-lg highlight-value">${realmMatch[2]} / ${realmMatch[3]}</div>
                    </div>
                </div>
                <div class="w-full progress-bar-bg rounded-full h-1.5 mt-2"><div class="h-1.5 rounded-full" style="${cultivationBarStyle}"></div></div>
                <p class="mt-4"><span class="font-semibold text-gray-400">技艺: </span><span class="text-white">${kvs['技艺'] || '无'}</span></p>
            `;
        }

        function renderCoreSubPanel() {
            let repListHtml = (data.core.声望.length === 0) ? `<div class="text-center text-gray-400 italic p-4">暂无声望</div>` : `<ul class="space-y-2 text-sm">${data.core.声望.map(i => `<li><span class="font-semibold">${i.key}:</span> <span class="highlight-value">${i.value}</span></li>`).join('')}</ul>`;
            const repContent = `<div class="scrollable-content">${repListHtml}</div>`;
            let itemListHtml = (data.core.持有物品.length === 0) ? `<div class="text-center text-gray-400 italic p-4">背包为空</div>` : `<ul class="space-y-2 text-sm">${data.core.持有物品.map(i => `<li class="p-2 bg-black/10 rounded-md"><span class="highlight-value">${i.key}:</span> ${i.value}</li>`).join('')}</ul>`;
            const itemContent = `<div class="scrollable-content">${itemListHtml}</div>`;
            return `<div class="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <section><h2 class="text-2xl font-bold text-yellow-400 panel-title mb-4">声望</h2>${repContent}</section>
                        <section><h2 class="text-2xl font-bold text-yellow-400 panel-title mb-4">持有物品</h2>${itemContent}</section>
                    </div>`;
        }

        function renderSkillsPanel() {
            const tabs = ['功法', '神通', '法宝'].map(title => {
                const items = data.skills[title];
                let content = `<div class="scrollable-content space-y-4">`;
                if (items.length === 0 || (items.length > 0 && (items[0].key === '暂无' || items[0].key === '无'))) {
                    content += `<div class="p-4 text-center text-gray-400 italic">尚未习得此类能力</div>`;
                } else {
                    content += items.map(item => `<div class="p-4 bg-black/20 rounded-lg border border-gray-700/50">
                        <p class="font-semibold">${item.key.replace(/\|/g, ' | <span class="text-blue-300">')}</p>
                        <p class="text-sm item-description">${item.value}</p>
                    </div>`).join('');
                }
                content += '</div>';
                return { title, content };
            });
            return `<h2 class="text-2xl font-bold text-yellow-400 panel-title mb-4">功法装备</h2>${createNestedTabs(tabs, 'skills-tabs')}`;
        }

        function renderAttributesPanel() {
            const radarContent = `<div class="h-64 md:h-80"><canvas id="radar-chart"></canvas></div>`;
            const tabs = [
                { title: '基础属性', content: radarContent },
                ...['特殊体质', '特殊血脉', '特殊气运'].map(title => {
                    const items = data.attributes[title];
                    let content = `<div class="scrollable-content space-y-2 text-sm">`;
                    if (items.length === 0 || (items.length > 0 && (items[0].key === '暂无' || items[0].key === '无'))) content += `<div class="p-4 text-center text-gray-400 italic">无</div>`;
                    else content += items.map(item => `<p><b>${item.key}:</b> <span class="item-description">${item.value}</span></p>`).join('');
                    content += '</div>';
                    return { title, content };
                })
            ];
            return `<h2 class="text-2xl font-bold text-yellow-400 panel-title mb-4">个人属性</h2><div class="p-4 bg-black/20 rounded-lg border border-gray-700/50">${createNestedTabs(tabs, 'attr-tabs')}</div>`;
        }

        function renderRelationsPanel() {
            const tabs = ['道侣', '当前互动'].map(title => {
                const characters = data.relations[title];
                let content = `<div class="scrollable-content space-y-3 text-sm">`;
                if (characters.length === 0) content += `<div class="p-4 text-center text-gray-400 italic">无</div>`;
                else {
                    content += characters.map(char => {
                        const details = char.details.map(d => `<p><span class="item-description">${d.key}: ${d.value}</span></p>`).join('');
                        return `<div class="p-3 bg-black/20 rounded">
                                    <p class="font-semibold text-base">${char.name}</p>
                                    ${details}
                                </div>`;
                    }).join('');
                }
                content += '</div>';
                return { title, content };
            });
            return `<h2 class="text-2xl font-bold text-yellow-400 panel-title mb-4">人物关系</h2><div class="p-4 bg-black/20 rounded-lg border border-gray-700/50">${createNestedTabs(tabs, 'rel-tabs')}</div>`;
        }

        // 【修改】重构系统面板渲染，以支持多种任务
        function renderSystemPanel() {
            if (!data.system || Object.keys(data.system.kvs).length === 0) {
                 return `<div class="section-divider"></div><section class="p-6 rounded-lg special-section text-center text-violet-300 italic">当前未激活系统</section>`;
            }

            const kvs = data.system.kvs;

            // 辅助函数，用于渲染单个任务区块
            function createTaskHtml(title, taskData) {
                if (!taskData || taskData.length === 0 || (taskData[0] && taskData[0].key === '任务: 暂无')) {
                    return `<div><h3 class="text-lg font-semibold text-violet-400 mb-2">【${title}】</h3><p class="text-gray-400 italic">暂无</p></div>`;
                }
                const taskContent = taskData.map(i => `<p class="text-sm"><span class="text-gray-400">${i.key}: </span>${i.key === '奖励' ? `<span class="text-yellow-300">${i.value}</span>` : i.value}</p>`).join('');
