            const isAttrEmpty = Object.values(data.attributes).every(arr => arr.length === 0);
            if(isAttrEmpty){
                attrCard.innerHTML = `<div class="placeholder-message">属性面板暂无特殊信息</div>`;
            } else {
                let attrHtml = renderListBlock('基础属性', data.attributes.基础属性);
                attrHtml += renderListBlock('特殊体质', data.attributes.特殊体质);
                attrHtml += renderListBlock('特殊血脉', data.attributes.特殊血脉);
                attrHtml += renderListBlock('特殊气运', data.attributes.特殊气运);
                attrCard.innerHTML = attrHtml;
            }

            const skillsCard = container.querySelector('#card-skills .card-content');
            const isSkillsEmpty = Object.values(data.skills).every(arr => arr.length === 0);
            if(isSkillsEmpty){
                skillsCard.innerHTML = `<div class="placeholder-message">功法装备暂无信息，请努力修行</div>`;
            } else {
                let skillsHtml = renderListBlock('功法', data.skills.功法);
                skillsHtml += renderListBlock('神通', data.skills.神通);
                skillsHtml += renderListBlock('法宝', data.skills.法宝);
                skillsCard.innerHTML = skillsHtml;
            }

            const relationsCard = container.querySelector('#card-relations .card-content');
            const isRelationsEmpty = Object.values(data.relations).every(arr => arr.length === 0);
            if(isRelationsEmpty){
                relationsCard.innerHTML = `<div class="placeholder-message">当前暂无人物关系信息</div>`;
            } else {
                let relationsHtml = '';
                for(const blockTitle of ['道侣', '当前互动']){
                    const characters = data.relations[blockTitle];
                    if (!characters || characters.length === 0) continue;
                    relationsHtml += `<div class="sub-card"><div class="sub-card-header">${blockTitle}</div>`;
                    if (characters[0] && characters[0].name) {
                        characters.forEach(char => {
                            const detailsHtml = char.details.map(d => `<div><b>${d.key}:</b> ${d.value}</div>`).join('');
                            relationsHtml += `<div class="character-card sub-card"><div class="sub-card-header">${char.name}</div><div class="info-item">${detailsHtml}</div></div>`;
                        });
                    } else {
                         relationsHtml += `<div class="placeholder-inline" style="padding:10px;">暂无</div>`;
                    }
                    relationsHtml += `</div>`;
                }
                relationsCard.innerHTML = relationsHtml;
            }

            const systemCard = container.querySelector('#card-system .card-content');
            const isSystemEmpty = Object.keys(data.system.kvs).length === 0 && data.system.主线任务.length === 0 && data.system.支线任务.length === 0;
            if(isSystemEmpty){
                systemCard.innerHTML = `<div class="placeholder-message">系统面板暂无信息</div>`;
            } else {
                let systemHtml = `<div class="info-item">${Object.entries(data.system.kvs).map(([k,v]) => `<b>${k}:</b> ${v}`).join('<br>')}</div>`;
                systemHtml += renderListBlock('主线任务', data.system.主线任务);
                systemHtml += renderListBlock('支线任务', data.system.支线任务);
                systemCard.innerHTML = systemHtml;
            }

            // --- 交互事件 ---
            container.querySelectorAll('.card-header').forEach(header => {
                header.addEventListener('click', () => {
                    const card = header.closest('.collapsible-card');
                    const toggle = header.querySelector('.collapse-toggle');
                    card.classList.toggle('collapsed');
                    toggle.textContent = card.classList.contains('collapsed') ? '[ 展开 ]' : '[ 收起 ]';
                });
            });
        })();
    </script>
</body>
</html>
